#
# Replaces the default plugin Conan generates here. It no longer carries
# Conan's "This file was generated by Conan" marker, so Conan won't
# overwrite it.


def compatibility(conanfile):  # pylint: disable=unused-argument
    """Never accept a binary built for a different configuration.

    Conan's default plugin treats every other compiler.cppstd (and cstd) as
    compatible, so a missing binary can be satisfied by one built against a
    different C++ standard. The images built here implement the VFX
    Reference Platform (https://vfxplatform.com), which pins the compiler
    and C++ standard per year: such a substitute would be a wrong binary,
    not an acceptable fallback. Returning no compatible configurations
    means a binary either matches the profile exactly or gets rebuilt.
    """
    return []
